import { describe, expect, it } from "vitest";

import {
  agentPrintArgument,
  assertBackgroundArgvDurable,
  canonicalizeBackgroundSessionArgv,
  stripFirstTurnPromptArgv,
  transformBackgroundLaunchArgv,
} from "../../src/lib/background-command-argv.js";

/**
 * Independent regression coverage for "含空格参数完整性": values containing
 * spaces, empty arguments and quoted paths must survive every argv transform
 * as single, byte-for-byte tokens — never split, dropped or shell-expanded.
 * All option grammar below mirrors a real Commander invocation so the parser
 * classifies tokens by arity, not by string equality.
 */
const ARGV_OPTION_SPECS = [
  { long: "--model", required: true },
  { long: "--title", required: true },
  { long: "--add-dir", required: true },
  { long: "--background" },
  { long: "--worktree" },
  { long: "--no-worktree" },
  { long: "--session", required: true },
  { long: "--resume", optional: true },
];

const SESSION_OPTION_SPECS = [
  { long: "--model", required: true },
  { long: "--title", required: true },
  { long: "--session", required: true },
  { long: "--resume", optional: true },
  { long: "--fork-session" },
];

describe("verify-12 spaced argument integrity", () => {
  it("keeps a spaced session value as one argv token and preserves an empty value", () => {
    // Positive: a multi-space value is consumed as a single element and survives
    // canonicalization without being re-split or re-parsed.
    expect(
      canonicalizeBackgroundSessionArgv(
        ["agent", "--title", "task title here", "go"],
        { sessionId: "resolved", optionSpecs: SESSION_OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "task title here", "go", "--session", "resolved"]);

    // Negative control: change only the value to an empty string; the empty
    // argument must still occupy its own slot, not be dropped.
    expect(
      canonicalizeBackgroundSessionArgv(
        ["agent", "--title", "", "go"],
        { sessionId: "resolved", optionSpecs: SESSION_OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "", "go", "--session", "resolved"]);
  });

  it("preserves a quoted path with spaces while stripping background parent options", () => {
    // Positive: a quoted/space-bearing path operand stays whole and parent-only
    // options are removed by grammar, then canonical directories are appended.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "C:\\Program Files\\thing.exe", "--title", "a b c", "--background", "--worktree"],
        { directories: ["/root/z"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual([
      "agent",
      "C:\\Program Files\\thing.exe",
      "--title",
      "a b c",
      "--add-dir",
      "/root/z",
    ]);

    // Negative control: change only the operand to an empty string; the empty
    // position is still retained in the transformed argv.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "", "--title", "a b c", "--background"],
        { directories: ["/root/z"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "", "--title", "a b c", "--add-dir", "/root/z"]);
  });

  it("replaces only grammar-identified --add-dir and keeps an equal option value", () => {
    // Positive: a real --add-dir option is recognized and swapped for the
    // canonical directory token.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "--add-dir", "real", "task"],
        { directories: ["/root/z"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "task", "--add-dir", "/root/z"]);

    // Negative control: change only the leading token so "--add-dir" becomes
    // the consumed value of --title; that byte-for-byte token must stay intact
    // rather than being treated as the directory option.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "--title", "--add-dir", "task"],
        { directories: ["/root/z"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "--add-dir", "task", "--add-dir", "/root/z"]);
  });

  it("strips operands but keeps spaced option values and option-named values", () => {
    // Positive: a multi-word option value survives while true operands are
    // dropped from the follow-up argv.
    expect(
      stripFirstTurnPromptArgv(
        ["agent", "--title", "multi word", "task", "--model", "m"],
        { optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "multi word", "--model", "m"]);

    // Negative control: change only the value to an option name ("--model");
    // it is consumed as the --title value and preserved, not re-parsed.
    expect(
      stripFirstTurnPromptArgv(
        ["agent", "--title", "--model", "task"],
        { optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "--model"]);
  });

  it("keeps a spaced/quoted prompt inside a single print token even when option-like", () => {
    // Positive: spaces and embedded quotes stay inside one --print token.
    expect(agentPrintArgument('dir with "quotes" and  spaces')).toBe(
      '--print=dir with "quotes" and  spaces',
    );

    // Negative control: change only the prompt to start with "-"; the token is
    // still emitted as one --print value, never re-split into options.
    expect(agentPrintArgument("-v --help")).toBe("--print=-v --help");
    expect(agentPrintArgument("")).toBe("--print=");
  });

  it("appends canonical directory paths that contain spaces as single tokens", () => {
    // Positive: directory roots themselves may contain spaces; each appended
    // --add-dir pair is one token pair, preserving the directory boundary.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "task"],
        { directories: ["/root/a b", "/root/c d"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "task", "--add-dir", "/root/a b", "--add-dir", "/root/c d"]);

    // Negative control: a single spaced directory still arrives as one token,
    // not two separate operands.
    expect(
      transformBackgroundLaunchArgv(
        ["agent", "task"],
        { directories: ["/root/single spaced"], optionSpecs: ARGV_OPTION_SPECS },
      ),
    ).toEqual(["agent", "task", "--add-dir", "/root/single spaced"]);
  });

  it("preserves literal spaced prompt data and only rejects a real --ephemeral", () => {
    // Positive: a literal "--ephemeral" after the terminator is prompt data,
    // not a durability violation; spaced prompt text is preserved.
    expect(() =>
      assertBackgroundArgvDurable(["agent", "--session", "s", "--", "--ephemeral"]),
    ).not.toThrow();

    // Negative control: change only the token position so "--ephemeral" is a
    // real option; the guard must reject it.
    expect(() =>
      assertBackgroundArgvDurable(["agent", "--ephemeral", "-p", "task"]),
    ).toThrowError(
      expect.objectContaining({ code: "BACKGROUND_EPHEMERAL_UNSUPPORTED" }),
    );
  });
});

import { describe, expect, it } from "vitest";

import {
  agentPrintArgument,
  assertBackgroundArgvDurable,
  canonicalizeBackgroundSessionArgv,
  stripFirstTurnPromptArgv,
  transformBackgroundLaunchArgv,
} from "../../src/lib/background-command-argv.js";

/**
 * Mirrors the Commander option grammar used by the real background launcher.
 * Defined locally so this suite stays independent of any existing unit test.
 */
const OPTION_SPECS = [
  { long: "--model", required: true },
  { long: "--title", required: true },
  { short: "-p", long: "--print", optional: true },
  { short: "-c", long: "--continue" },
  { long: "--session", required: true },
  { long: "--resume", optional: true },
  { long: "--fork-session" },
  { long: "--fork-request-id", required: true },
  { short: "-y", long: "--yolo" },
  { long: "--verbose" },
  { long: "--profile", required: true },
];

describe("verify-12: argument integrity with spaces, empty values, and quoted paths", () => {
  it("keeps an option value with spaces as a single token and drops it only when it is a parent option", () => {
    // Positive control: a value containing spaces is one argv element and is
    // carried through verbatim. A value that happens to be a literal empty
    // string stays a present (not dropped) element.
    const spaced = canonicalizeBackgroundSessionArgv(
      ["agent", "--title", "hello world", "--session=old", "task"],
      { sessionId: "resolved", optionSpecs: OPTION_SPECS },
    );
    expect(spaced).toEqual([
      "agent",
      "--title",
      "hello world",
      "task",
      "--session",
      "resolved",
    ]);

    // Negative control for the same option-boundary logic: an empty string is
    // still a real value token of --title and must not be mistaken for a flag.
    const empty = canonicalizeBackgroundSessionArgv(
      ["agent", "--title", "", "--session", "old"],
      { sessionId: "resolved", optionSpecs: OPTION_SPECS },
    );
    expect(empty).toEqual(["agent", "--title", "", "--session", "resolved"]);
  });

  it("keeps a quoted path with spaces inside one token instead of splitting it on whitespace", () => {
    // Positive control: the platform passes a quoted path as a single argv
    // element; the transform must not re-split it.
    const launched = transformBackgroundLaunchArgv(
      [
        "agent",
        "--model",
        "C:\\Program Files\\model.bin",
        "--no-worktree",
        "--title",
        "work",
      ],
      { optionSpecs: OPTION_SPECS },
    );
    expect(launched).toEqual([
      "agent",
      "--model",
      "C:\\Program Files\\model.bin",
      "--title",
      "work",
    ]);

    // Negative control: a real --no-worktree option (grammar-identified) is
    // removed, while the identical-looking value under --model is retained.
    const retained = transformBackgroundLaunchArgv(
      ["agent", "--model", "--no-worktree", "--title", "work"],
      { optionSpecs: OPTION_SPECS },
    );
    expect(retained).toEqual(["agent", "--model", "--no-worktree", "--title", "work"]);
  });

  it("holds a prompt with spaces or leading dashes inside a single --print token", () => {
    // Positive control: whitespace inside the prompt stays inside one token
    // because it is glued onto --print=, so no shell split can occur.
    expect(agentPrintArgument("refactor this file now")).toBe(
      "--print=refactor this file now",
    );
    expect(agentPrintArgument("--help")).toBe("--print=--help");

    // Negative control: the empty prompt still produces exactly one token
    // (--print= with an empty payload), never a split or a dropped argument.
    expect(agentPrintArgument("")).toBe("--print=");
  });

  it("strips the first-turn operand but never corrupts a spaced option value", () => {
    // Positive control: a required option with a spaced value survives intact
    // while the prompt operand is removed.
    const stripped = stripFirstTurnPromptArgv(
      ["agent", "--title", "a title with spaces", "prompt text", "--session", "s"],
      { optionSpecs: OPTION_SPECS },
    );
    expect(stripped).toEqual([
      "agent",
      "--title",
      "a title with spaces",
      "--session",
      "s",
    ]);

    // Negative control: an empty-string operand is dropped, and the option
    // token/value boundary of the following --session stays untouched.
    const strippedEmpty = stripFirstTurnPromptArgv(
      ["agent", "--title", "kept", "", "--session", "s"],
      { optionSpecs: OPTION_SPECS },
    );
    expect(strippedEmpty).toEqual(["agent", "--title", "kept", "--session", "s"]);
  });

  it("rejects an ephemeral authority token but allows the same literal after --", () => {
    // Negative control: --ephemeral anywhere before the terminator is an
    // unsupported durable-authority violation.
    expect(() =>
      assertBackgroundArgvDurable([
        "agent",
        "--title",
        "ephemeral work",
        "--ephemeral",
      ]),
    ).toThrowError(
      expect.objectContaining({ code: "BACKGROUND_EPHEMERAL_UNSUPPORTED" }),
    );

    // Positive control: the identical literal after -- is prompt data, not an
    // option, and must not be rejected.
    expect(() =>
      assertBackgroundArgvDurable([
        "agent",
        "--session",
        "durable",
        "--",
        "--ephemeral",
      ]),
    ).not.toThrow();
  });

  it("retains option-shaped values verbatim instead of collapsing them into options", () => {
    // Positive control: a --title value that looks like an option name is a
    // value, so it is preserved byte-for-byte and no second option appears.
    expect(
      canonicalizeBackgroundSessionArgv(
        ["agent", "--title", "--session", "--model", "x"],
        { sessionId: "resolved", optionSpecs: OPTION_SPECS },
      ),
    ).toEqual([
      "agent",
      "--title",
      "--session",
      "--model",
      "x",
      "--session",
      "resolved",
    ]);

    // Negative control: when --session is a real option with an attached value
    // spelling, it is canonicalized away as expected.
    expect(
      canonicalizeBackgroundSessionArgv(
        ["agent", "--session=old", "--title", "t"],
        { sessionId: "resolved", optionSpecs: OPTION_SPECS },
      ),
    ).toEqual(["agent", "--title", "t", "--session", "resolved"]);
  });
});

